    guideQuickstartTitle: 'Guia do PomoBot - Início rápido',
    guideQuickstartBody: '**Novo por aqui? Comece com estes 3 passos:**\n\n1. Use `/study` para um timer de focus normal.\n2. Use `/daily` e `/quests daily` para coletar Água.\n3. Use `/garden` para plantar, regar e colher.\n\nSe o servidor tiver voice tracking automático, entrar em um canal de estudo configurado também pode contar como tempo de focus.',
