    guideSoloBody: '**Use `/study` quando quiser um timer simples.**\n\n- `/study 25 math` inicia uma sessão de 25 minutos.\n- As recompensas chegam quando a sessão termina.\n- Use `/pomodoro` para ciclos automáticos de trabalho/pausa.\n- Use `/cancel` se iniciou a sessão errada.',
    guideVoiceTitle: 'Guia de voice tracking',
    guideVoiceBody: '**Voice tracking só funciona automaticamente depois que um manager configura.**\n\n- Managers usam `/setup start` ou `/voice setup`.\n- Se o canal de voz estiver dentro da categoria configurada, Pomo rastreia automaticamente.\n- Sobreposição com timers slash é removida para evitar farm duplicado.\n- Use `/voice settings` para ver as regras do servidor.',
    guideServerTitle: 'Guia de setup do servidor',
    guideServerBody: '**Para server managers:**\n\n1. Rode `/setup start`.\n2. Escolha um canal de voz ou categoria de estudo.\n3. Escolha um canal de relatório semanal.\n4. Use `/setup status` para confirmar tudo.\n\nDepois do setup, membros podem estudar com `/study`, `/team`, `/pomodoro` ou canais de voz configurados.',
    guideGardenTitle: 'Guia de Jardim & Recompensas',
    guideGardenBody: '**Pomo transforma focus em progresso.**\n\n- Sessões dão Água, XP e progresso de streak.\n- Gaste Água no `/market` com sementes, boosts e temas de perfil.\n- Use `/garden` para plantar, regar e colher.\n- Use `/pet feed` para alimentar seu pet ativo com colheitas.',
    guideActivityTitle: 'Guia do Discord Activity',
    guideActivityBody: '**Pomo Activity é a sala visual de focus dentro do voice do Discord.**\n\n- Inicie um timer pela Activity e Pomo cria a sessão real no Discord.\n- Use Chat para conversar com outros usuários focados.\n- Use Group Study para criar ou entrar em uma sala compartilhada.\n- Use Ambience para sons de estudo e Garden para gastar Água.',
    guideNeedMoreHelpTitle: 'Precisa de mais ajuda?',
    guideNeedMoreHelpBody: 'Use `/help` para a lista completa de comandos, `/setup status` para configuração do servidor, ou pergunte no support server.',
