Object.assign(Messages.fr, {
    guideQuickstartTitle: 'Guide PomoBot - Démarrage rapide',
    guideQuickstartBody: '**Nouveau ici ? Commence avec ces 3 étapes :**\n\n1. Utilise `/study` pour un timer focus simple.\n2. Utilise `/daily` et `/quests daily` pour récupérer de l’eau.\n3. Utilise `/garden` pour planter, arroser et récolter.\n\nSi le serveur a le voice tracking automatique, rejoindre un salon vocal configuré peut aussi compter comme temps focus.',
    guideSoloTitle: 'Guide study solo',
    guideSoloBody: '**Utilise `/study` pour un timer simple.**\n\n- `/study 25 math` lance une session de 25 minutes.\n- Les récompenses arrivent à la fin de session.\n- Utilise `/pomodoro` pour des cycles travail/pause automatiques.\n- Utilise `/cancel` si tu as lancé la mauvaise session.',
    guideVoiceTitle: 'Guide voice tracking',
    guideVoiceBody: '**Le voice tracking est automatique seulement après configuration par un manager.**\n\n- Les managers utilisent `/setup start` ou `/voice setup`.\n- Si ton salon vocal est dans la catégorie configurée, Pomo le suit automatiquement.\n- Le chevauchement avec les timers slash est retiré pour éviter les doubles rewards.\n- Utilise `/voice settings` pour voir les règles du serveur.',
    guideServerTitle: 'Guide setup serveur',
    guideServerBody: '**Pour les server managers :**\n\n1. Lance `/setup start`.\n2. Choisis un salon vocal ou une catégorie study.\n3. Choisis un salon pour les rapports hebdomadaires.\n4. Utilise `/setup status` pour vérifier.\n\nAprès le setup, les membres peuvent étudier avec `/study`, `/team`, `/pomodoro` ou les salons vocaux configurés.',
    guideGardenTitle: 'Guide Jardin & Récompenses',
    guideGardenBody: '**Pomo transforme le focus en progression.**\n\n- Les sessions donnent eau, XP et progression de streak.\n- Dépense l’eau dans `/market` pour des graines, boosts et thèmes de profil.\n- Utilise `/garden` pour planter, arroser et récolter.\n- Utilise `/pet feed` pour donner les récoltes à ton pet actif.',
    guideActivityTitle: 'Guide Discord Activity',
    guideActivityBody: '**Pomo Activity est la salle focus visuelle dans le vocal Discord.**\n\n- Lance un timer depuis l’Activity et Pomo crée la vraie session dans Discord.\n- Utilise Chat pour parler avec les autres utilisateurs focus.\n- Utilise Group Study pour créer ou rejoindre une room partagée.\n- Utilise Ambience pour les sons study et Garden pour utiliser ton eau.',
    guideNeedMoreHelpTitle: 'Besoin de plus d’aide ?',
    guideNeedMoreHelpBody: 'Utilise `/help` pour la liste complète des commandes, `/setup status` pour la configuration serveur, ou demande dans le support server.',
    guideFooter: 'Astuce : les server managers devraient commencer avec /setup start',
    setupShareField: 'À partager avec les membres',
    setupShareBody: '`/guide` explique les bases.\n`/study 25` lance un timer focus simple.\n`/pomodoro` lance des cycles travail/pause.\nLes salons vocaux configurés suivent le focus automatiquement.',
    setupAfterCompleteNextStepBody: 'Essaie `/serverstats` après les premières sessions, puis utilise `/goal setup` pour créer un challenge hebdomadaire commun.',
    setupFooter: 'PomoBot n’a pas besoin de la permission Administrateur.',
});

Object.assign(Messages.es, {
    guideQuickstartTitle: 'Guía de PomoBot - Inicio rápido',
    guideQuickstartBody: '**¿Nuevo aquí? Empieza con estos 3 pasos:**\n\n1. Usa `/study` para un temporizador focus normal.\n2. Usa `/daily` y `/quests daily` para conseguir Agua.\n3. Usa `/garden` para plantar, regar y cosechar.\n\nSi el servidor tiene voice tracking automático, entrar a un canal de estudio configurado también puede contar como tiempo de focus.',
    guideSoloTitle: 'Guía de estudio solo',
    guideSoloBody: '**Usa `/study` cuando quieras un temporizador simple.**\n\n- `/study 25 math` inicia una sesión de 25 minutos.\n- Las recompensas llegan cuando termina la sesión.\n- Usa `/pomodoro` si quieres ciclos automáticos de trabajo/descanso.\n- Usa `/cancel` si iniciaste la sesión equivocada.',
    guideVoiceTitle: 'Guía de voice tracking',
    guideVoiceBody: '**Voice tracking solo es automático después de que un manager lo configure.**\n\n- Managers usan `/setup start` o `/voice setup`.\n- Si tu canal de voz está dentro de la categoría configurada, Pomo lo rastrea automáticamente.\n- El solapamiento con timers slash se elimina para evitar recompensas duplicadas.\n- Usa `/voice settings` para revisar las reglas del servidor.',
    guideServerTitle: 'Guía de configuración del servidor',
    guideServerBody: '**Para server managers:**\n\n1. Ejecuta `/setup start`.\n2. Elige un canal de voz o categoría de estudio.\n3. Elige un canal para reportes semanales.\n4. Usa `/setup status` para confirmar todo.\n\nDespués del setup, los miembros pueden estudiar con `/study`, `/team`, `/pomodoro` o canales de voz configurados.',
    guideGardenTitle: 'Guía de Jardín y Recompensas',
    guideGardenBody: '**Pomo convierte focus en progreso.**\n\n- Las sesiones dan Agua, XP y progreso de streak.\n- Gasta Agua en `/market` para semillas, boosts y temas de perfil.\n- Usa `/garden` para plantar, regar y cosechar.\n- Usa `/pet feed` para alimentar tu pet activo con cultivos.',
    guideActivityTitle: 'Guía de Discord Activity',
    guideActivityBody: '**Pomo Activity es la sala visual de focus dentro del voice de Discord.**\n\n- Inicia un timer desde Activity y Pomo crea la sesión real en Discord.\n- Usa Chat para hablar con otros usuarios enfocados.\n- Usa Group Study para crear o unirte a una sala compartida.\n- Usa Ambience para sonidos de estudio y Garden para gastar Agua.',
    guideNeedMoreHelpTitle: '¿Necesitas más ayuda?',
    guideNeedMoreHelpBody: 'Usa `/help` para la lista completa de comandos, `/setup status` para configuración del servidor, o pregunta en el support server.',
    guideFooter: 'Tip: server managers deberían empezar con /setup start',
    setupShareField: 'Comparte esto con los miembros',
    setupShareBody: '`/guide` explica lo básico.\n`/study 25` inicia un timer focus simple.\n`/pomodoro` inicia ciclos de trabajo/descanso.\nLos canales de voz configurados rastrean focus automáticamente.',
    setupAfterCompleteNextStepBody: 'Prueba `/serverstats` después de que los miembros estudien, luego usa `/goal setup` para crear un reto semanal compartido.',
    setupFooter: 'PomoBot no necesita permiso de Administrador.',
});

