    guideQuickstartBody: '**Для участников:**\n1. Используйте `/study 25` для простого таймера фокуса.\n2. Используйте `/daily` и `/quests daily`, чтобы получать воду.\n3. Используйте `/garden`, чтобы сажать, поливать и собирать растения.\n\n**Для менеджеров сервера:**\nЗапустите `/setup start`, чтобы включить автоматическое отслеживание голосовых каналов и еженедельные отчёты. После настройки вход в настроенный учебный голосовой канал может автоматически засчитываться как время фокуса.',
