function normalizeLanguage(language) {
    return SupportedLanguages[language] ? language : 'en';
}

function languageLabel(language) {
    const entry = SupportedLanguages[normalizeLanguage(language)];
    return `${entry.flag} ${entry.native}`;
}

function t(language, key, vars = {}) {
    const lang = normalizeLanguage(language);
    const template = Messages[lang]?.[key] || Messages.en[key] || key;
    return template.replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? ''));
}

function getInteractionLanguage(interaction) {
    // No guild, or a server the bot isn't in (user install): use the user's locale.
    if (!interaction?.guildId || interaction.guild === null) {
        return normalizeLanguage(interaction?.locale || 'en');
    }

    try {
        const { getOrCreateGuildSettings } = require('./database');
        if (typeof getOrCreateGuildSettings === 'function') {
            const settings = getOrCreateGuildSettings(interaction.guildId);
            return normalizeLanguage(settings?.language || interaction.guildLocale || interaction.locale || 'en');
        }
    } catch {
        // Fall through to Discord locale / English fallback.
    }

    return normalizeLanguage(interaction.guildLocale || interaction.locale || 'en');
}

/**
 * Language for DMs sent outside an interaction (background jobs): the language
 * of the guild where the user was most recently active, else the fallback.
 */
function getUserLanguage(userId, fallback = 'en') {
    if (!userId) return normalizeLanguage(fallback);

    try {
        const { getUserActiveGuildLanguage } = require('./database');
        if (typeof getUserActiveGuildLanguage === 'function') {
            return normalizeLanguage(getUserActiveGuildLanguage(userId) || fallback);
        }
    } catch {
        // Fall through to the provided fallback.
    }

    return normalizeLanguage(fallback);
}

function getGuildLanguage(guildId, fallback = 'en') {
    if (!guildId) return normalizeLanguage(fallback);

    try {
        const { getOrCreateGuildSettings } = require('./database');
        if (typeof getOrCreateGuildSettings === 'function') {
            const settings = getOrCreateGuildSettings(guildId);
            return normalizeLanguage(settings?.language || fallback);
        }
    } catch {
        // Fall through to the provided fallback.
    }

    return normalizeLanguage(fallback);
}



