    "onboardingQuestsBody": "デイリークエストは継続的な学習に報酬を与えます。`/study`、`/team`、またはボイストラッキングを使うと、より早く達成できます。",
    "onboardingVoiceTitle": "ヒント: ボイストラッキングで自動記録できます",
    "onboardingVoiceBody": "このサーバーでボイストラッキングが有効なら、設定された勉強用ボイスチャンネルに参加するだけで集中時間が自動でカウントされます。",
    "onboardingFooter": "一度だけのヒントです。/help でいつでも PomoBot の機能を確認できます。",
