    "voiceNoReward": "報酬ブロックが完了していないか、1日のボイス報酬上限に達しました。",
    "voiceRewards": "水: **+{water}**\nXP: **+{xp}**",
    "levelUpLabel": "レベルアップ",
    "guideQuickstartTitle": "PomoBot ガイド - クイック スタート",
    "guideQuickstartBody": "**メンバー向け:**\n1. シンプルな集中タイマーには `/study 25` を使います。\n2. `/daily` と `/quests daily` で水を集めます。\n3. `/garden` で作物を植え、水をやり、収穫します。\n\n**サーバー管理者向け:**\n`/setup start` を実行すると、ボイスの自動トラッキングと週間レポートが有効になります。設定後は、指定した学習用ボイスチャンネルに参加するだけで自動的に集中時間としてカウントされます。",
    "guideSoloTitle": "ひとり勉強ガイド",
    "guideSoloBody": "**シンプルなタイマーが欲しいときは `/study` を使いましょう。**\n\n- `/study 25 math` で25分間のセッションを開始します。\n- 報酬はセッション終了時に付与されます。\n- 作業と休憩のサイクルを自動で回したい場合は `/pomodoro` を使います。\n- 間違ったセッションを開始した場合は `/cancel` を使ってください。",
    "guideVoiceTitle": "ボイストラッキングガイド",
    "guideVoiceBody": "**ボイストラッキングは、サーバー管理者が設定した後にのみ自動で動作します。**\n\n- 管理者は `/setup start` または `/voice setup` を実行します。\n- 参加しているボイスチャンネルが設定済みのカテゴリ内にあれば、Pomo が自動で記録します。\n- スラッシュコマンドのタイマーと重複した時間は除外されるため、報酬を二重に獲得することはできません。\n- サーバーのルールは `/voice settings` で確認できます。",
    "guideServerTitle": "サーバーセットアップガイド",
    "guideServerBody": "**管理者向けクイックセットアップ:**\n\n1. `/setup start` を実行します。\n2. 学習用のボイスチャンネルまたはカテゴリを選びます。\n3. 週間レポートを送るチャンネルを選びます。\n4. `/setup status` ですべての設定を確認します。\n\nその後、メンバーに `/guide` を共有しましょう。後から `/goal setup` で、サーバー共通の週間チャレンジを追加できます。",
    "guideGardenTitle": "ガーデンと報酬ガイド",
    "guideGardenBody": "**Pomo は集中を成長に変えます。**\n\n- 勉強セッションで水、XP、ストリークの進捗が得られます。\n- `/market` で水を使って、種、ブースト、プロフィールテーマを購入できます。\n- `/garden` で作物を植え、水をやり、収穫します。\n- 収穫した作物を `/pet feed` で与えると、装備中のペットがレベルアップします。",
    "guideActivityTitle": "Discordアクティビティガイド",
    "guideActivityBody": "**Pomo Activity は、Discord のボイスチャンネル内で使えるビジュアルな集中ルームです。**\n\n- Activity からタイマーを開始すると、Pomo が Discord 上に実際のセッションを作成します。\n- チャットで他の集中ユーザーと会話できます。\n- グループ学習で共有ルームを作成したり参加したりできます。\n- アンビエンスで学習用サウンドを流し、ガーデンで水を使えます。",
    "guideNeedMoreHelpTitle": "お困りですか？",
    "guideNeedMoreHelpBody": "コマンドの一覧は `/help`、サーバー設定の確認は `/setup status` を使うか、サポートサーバーで質問してください。",
    "guideFooter": "ヒント: サーバー管理者はまず /setup start から始めましょう",
    "setupShareField": "メンバーに共有しよう",
    "setupShareBody": "`/guide` で基本を確認できます。\n`/study 25` でシンプルな集中タイマーを開始します。\n`/pomodoro` で作業/休憩サイクルを開始します。\n設定済みの学習用ボイスチャンネルでは集中時間が自動で記録されます。",
    "setupAfterCompleteNextStepBody": "メンバーが勉強した後に `/serverstats` を試し、`/goal setup` でサーバー共通の週間チャレンジを作成しましょう。",
    "setupFooter": "PomoBot には管理者権限は必要ありません。",
