    "voteTitle": "Pomo に投票しよう！",
    "voteBody": "Top.gg でボットに投票すると、毎回 **+30 💧 水** がもらえます！\n\n**仕組み:**\n1. 下のボタンをクリックして Top.gg に移動します\n2. Pomo に投票します\n3. +30 💧 水の報酬が自動で追加されます！\n\n> ⚠️ 確認メッセージを受け取るには **Discord の DM を有効にしてください**。\n> DM がオフでも水は追加されます。`/profile` で確認してください。\n\n*投票は12時間に1回できます。*",
