    "petGuideTitle": "スタディペットガイド",
    "petGuideBody": "勉強すると、各ペットは **セッションで得た XP と同じ量の XP** を獲得します。\n`/pet feed` で収穫した作物を与えると、追加のペット XP も得られます。\nペットをレベルアップして、より強力なバフを手に入れましょう！（必要な XP = `レベル × 50`）\n\n**レア度によってレベルごとのバフ倍率が決まります:**\n⬜ コモン - **+5%/レベル**（Lv10 で最大 +50%）\n🟦 レア - **+8%/レベル**（Lv10 で最大 +80%）\n🟪 エピック - **+12%/レベル**（Lv10 で最大 +120%）\n🟨 レジェンダリー - **+20%/レベル**（Lv10 で最大 +200%）",
