    "petGuideBody": "يكسب كل حيوان أليف **XP مساويًا لـ XP جلستك** عندما تدرس.\nيمكنك أيضًا إطعامه محاصيل الحديقة المحصودة باستخدام `/pet feed` للحصول على XP إضافي للحيوان الأليف.\nارفع مستوى حيوانك الأليف للحصول على معزّزات أقوى! (XP المطلوب = `level × 50`)\n\n**تحدد الندرة مضاعِف المعزّز لكل مستوى:**\n⬜ عادي - **+5%/مستوى** (بحد أقصى +50% في المستوى 10)\n🟦 نادر - **+8%/مستوى** (بحد أقصى +80% في المستوى 10)\n🟪 ملحمي - **+12%/مستوى** (بحد أقصى +120% في المستوى 10)\n🟨 أسطوري - **+20%/مستوى** (بحد أقصى +200% في المستوى 10)",
