    "levelUpLabel": "레벨 업",
    "guideQuickstartTitle": "PomoBot 가이드 - 빠른 시작",
    "guideQuickstartBody": "**멤버용:**\n1. 간단한 집중 타이머는 `/study 25` 명령어를 사용하세요.\n2. `/daily`와 `/quests daily`로 물을 모으세요.\n3. `/garden`에서 작물을 심고, 물을 주고, 수확하세요.\n\n**서버 관리자용:**\n`/setup start` 명령어를 실행해 자동 음성 추적과 주간 보고서를 활성화하세요. 설정 후에는 지정된 공부 음성 채널에 참여하면 자동으로 집중 시간으로 계산될 수 있습니다.",
    "guideSoloTitle": "혼자 공부하기 가이드",
    "guideSoloBody": "**간단한 타이머가 필요하면 `/study` 명령어를 사용하세요.**\n\n- `/study 25 math` 명령어는 25분 세션을 시작합니다.\n- 보상은 세션이 끝날 때 지급됩니다.\n- 작업/휴식 사이클을 자동으로 반복하려면 `/pomodoro` 명령어를 사용하세요.\n- 세션을 잘못 시작했다면 `/cancel` 명령어를 사용하세요.",
    "guideVoiceTitle": "음성 추적 가이드",
    "guideVoiceBody": "**음성 추적은 서버 관리자가 설정한 후에만 자동으로 작동합니다.**\n\n- 관리자가 `/setup start` 또는 `/voice setup` 명령어를 실행합니다.\n- 음성 채널이 설정된 카테고리 안에 있으면 Pomo가 자동으로 추적합니다.\n- 슬래시 타이머와 겹치는 시간은 제외되므로 보상을 중복으로 얻을 수 없습니다.\n- 서버 규칙을 확인하려면 `/voice settings` 명령어를 사용하세요.",
    "guideServerTitle": "서버 설정 가이드",
    "guideServerBody": "**빠른 관리자 설정:**\n\n1. `/setup start` 명령어를 실행하세요.\n2. 공부용 음성 채널 또는 카테고리를 선택하세요.\n3. 주간 보고서 채널을 선택하세요.\n4. `/setup status` 명령어로 모든 설정을 확인하세요.\n\n그런 다음 멤버들에게 `/guide` 명령어를 공유하세요. 나중에 `/goal setup` 명령어로 서버 공동 주간 챌린지를 추가할 수 있습니다.",
    "guideGardenTitle": "정원 및 보상 안내",
    "guideGardenBody": "**Pomo는 집중을 성장으로 바꿔 줍니다.**\n\n- 공부 세션을 하면 물, XP, 연속 기록 진행도를 얻습니다.\n- `/market`에서 물로 씨앗, 부스트, 프로필 테마를 구매하세요.\n- `/garden`에서 작물을 심고, 물을 주고, 수확하세요.\n- 수확한 작물을 `/pet feed` 명령어로 먹이면 활성 펫의 레벨이 오릅니다.",
    "guideActivityTitle": "Discord Activity 가이드",
    "guideActivityBody": "**Pomo Activity는 Discord 음성 채널 안의 시각적인 집중 공간입니다.**\n\n- Activity에서 타이머를 시작하면 Pomo가 Discord에 실제 세션을 만듭니다.\n- 채팅으로 다른 집중 사용자와 대화하세요.\n- 그룹 스터디로 공유 방을 만들거나 참여하세요.\n- 앰비언스로 공부용 사운드를 듣고, 정원에서 물을 사용하세요.",
