    "petGuideTitle": "공부 펫 가이드",
    "petGuideBody": "공부하면 각 펫은 **세션 XP와 같은 양의 XP**를 얻습니다.\n수확한 정원 작물을 `/pet feed` 명령어로 먹여 펫 XP를 추가로 얻을 수도 있습니다.\n펫 레벨을 올려 더 강한 버프를 받으세요! (필요 XP = `level × 50`)\n\n**희귀도에 따라 레벨당 버프 배율이 달라집니다:**\n⬜ 일반 - **레벨당 +5%** (Lv10에서 최대 +50%)\n🟦 희귀 - **레벨당 +8%** (Lv10에서 최대 +80%)\n🟪 에픽 - **레벨당 +12%** (Lv10에서 최대 +120%)\n🟨 전설 - **레벨당 +20%** (Lv10에서 최대 +200%)",
