    premiumVerifyRejectedBody: 'Boosty aboneliğini doğrulayamadık.\n\n**Verilen kimlik:** `{identifier}`\n\nBoosty kullanıcı adını kontrol et ve `/premium activate` ile tekrar dene.\nDoğrudan yardım için bot sahibiyle iletişime geç.',
    premiumWelcomeTitle: "Pomo Pro'ya Hoş Geldin!",
    premiumWelcomeBody: 'Aboneliğin doğrulandı, **{username}**. Pro artık aktif!',
