    premiumWelcomePersonaValue: 'Personanı istediğin zaman değiştir — 30 günlük bekleme yok',
    premiumWelcomeFooter: 'Tüm Pro detaylarını görmek için /premium status kullan.',
    premiumExpiryDm: "💔 **Pomo Pro aboneliğinin süresi doldu.**\n\nPro avantajların şimdilik durduruldu, ama XP, streak ve bahçe verilerin güvende.\n\nTekrar aktifleştirmek için Boosty'de abone ol ve `/premium activate` çalıştır:\n→ <https://boosty.to/pomobot>",
    premiumBoostyConfirmedDm: '✅ **Pomo Pro aboneliğin onaylandı!**\n\nBoosty aboneliğini doğrularken geçici bir sorun yaşadık, ama artık her şey yolunda.\nPro erişimin tamamen aktif kalmaya devam ediyor.',
    premiumBoostyWarningDm: "⚠️ **Bilgin olsun!**\n\nBoosty'deki Pomo Pro aboneliğini doğrulamakta sorun yaşıyoruz. Bu genelde ödeme işleminde geçici bir gecikmedir.\n\n**Pro erişimin şu an hâlâ tamamen aktif.**\n\nÖdemen geçmediyse Boosty hesabını kontrol et:\n→ <https://boosty.to/pomobot>\n\nSenin tarafında her şey yolundaysa bir şey yapmana gerek yok — sonraki 30 dakika içinde otomatik olarak tekrar doğrulayacağız.",
    premiumBoostyLapseDm: "💔 **Pomo Pro üyeliğin sona erdi.**\n\nBirkaç kontrolden sonra Boosty'de aktif bir abonelik doğrulayamadık.\n\n**Duraklatılanlar:**\n🔒 Ekstra bahçe alanları *(bitkilerin güvende — sadece uyuyorlar)*\n🛡️ Streak Kalkanları\n📊 Gelişmiş Analizler\n\n**Hiçbir şey silinmez.** XP, streak ve bitkilerin hâlâ burada.\n\nTekrar aktifleştirmek için Boosty'de abone ol ve `/premium activate` çalıştır:\n→ <https://boosty.to/pomobot>",
    premiumBoostyAutoGrantDm: "🎉 **Pomo Pro'n otomatik olarak aktifleştirildi!**\n\nBoosty aboneliğini doğruladık ve hesabına Pro verdik.\n\n**Artık açık olanlar:**\n🛡️ 3 Streak Kalkanı eklendi\n🌱 2 ekstra bahçe alanı\n📊 Dashboard'unda gelişmiş analizler\n\nTüm Pro detaylarını görmek için `/premium status` kullan.",

    // reactivate
    reactivateDmTitle: "👋 Seni PomoBot'ta özledik!",
    reactivateDmBody: 'Selam **{username}**, son çalışma oturumundan bu yana epey zaman geçti!\n\nTekrar hoş geldin demek için hesabına tamamen ücretsiz **3 Günlük PomoBot PRO** tanımladık! 🎉\n\n🌟 **PRO ile şunların tadını çıkar:**\n- 💧 Her oturumda 2x Su\n- 🛡️ Kaçırdığın günlerde streakini koruyan {shields} Streak Kalkanı\n- 🌱 {plots} bahçe alanına kadar\n- 🎁 `/daily premium` ile ikinci bir günlük ödül\n\nPomoBot olan herhangi bir sunucuya gir ve premium avantajlarını kullanmaya başlamak için `/study` çalıştır. İyi focuslar!',
